    <h1>User Input Logger</h1>
    <form id="inputForm">
        <label for="userInput">Enter your input:</label>
        <input type="text" id="userInput" name="userInput" required>
        <button type="submit">Submit</button>
    </form>
    <div class="log" id="logContainer">
        <h2>Logged Inputs:</h2>
        <ul id="logList"></ul>
    </div>

    <script>
        const form = document.getElementById('inputForm');
        const logList = document.getElementById('logList');

        form.addEventListener('submit', async (event) => {
            event.preventDefault();
            const userInput = document.getElementById('userInput').value;

            // Send input to the server
            const response = await fetch('/log', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ input: userInput }),
            });

            if (response.ok) {
                const data = await response.json();
                const newLogItem = document.createElement('li');
                newLogItem.textContent = data.input;
                logList.appendChild(newLogItem);
                form.reset();
            } else {
                alert('Failed to log input.');
            }
        });
    </script>
</body>
</html>
```

### Backend (Node.js)
```javascript
const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;

// Middleware to parse JSON
app.use(express.json());

// Serve static files (frontend)
app.use(express.static(path.join(__dirname, 'public')));

// Endpoint to log user input
app.post('/log', (req, res) => {
    const userInput = req.body.input;

    if (!userInput) {
        return res.status(400).json({ error: 'Input is required' });
    }

    // Append input to a local file
    const logFilePath = path.join(__dirname, 'userInputs.txt');
    fs.appendFile(logFilePath, `${userInput}\n`, (err) => {
        if (err) {
            console.error('Failed to write to file:', err);
            return res.status(500).json({ error: 'Failed to log input' });
        }

        res.json({ input: userInput });
    });
});

// Start the server
app.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
```

